import{_ as r,a as l}from"./chunks/Apps20Filled.Br2iU9XK.js";import{_ as a}from"./chunks/Add16Regular.kVgxK51v.js";import{_ as e}from"./chunks/Delete24Regular.BPl04VSh.js";import{_ as i}from"./chunks/RecordStop20Regular.pf2cR3Tb.js";import{_ as o,c as d,o as n,a3 as s}from"./chunks/framework.CTM16EAR.js";const q=JSON.parse('{"title":"生活记录使用方法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reference/life.md","filePath":"guide/reference/life.md","lastUpdated":1792053356000}'),g={name:"guide/reference/life.md"};function h(c,t,u,m,b,p){return n(),d("div",null,t[0]||(t[0]=[s('<h1 id="生活记录使用方法" tabindex="-1">生活记录使用方法 <a class="header-anchor" href="#生活记录使用方法" aria-label="Permalink to &quot;生活记录使用方法&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>生活记录用来顺手记下 <strong>喝水、吃饭、活动、睡觉</strong>。日视图写明细；周 / 月 / 年打开图层看趋势。数据挂在当天对应任务上，登录后随任务一起云同步。</p></div><h2 id="快速导航" tabindex="-1">快速导航 <a class="header-anchor" href="#快速导航" aria-label="Permalink to &quot;快速导航&quot;">​</a></h2><ul><li>我想找入口：见 <a href="#入口与按钮">入口与按钮</a></li><li>我想知道记什么：见 <a href="#四类记录">四类记录</a></li><li>我想在某一天录入：见 <a href="#日视图录入">日视图录入</a></li><li>我想看一周 / 一月 / 一年：见 <a href="#周月年可视化">周月年可视化</a></li><li>我想在手机上预览：见 <a href="#手机预览">手机预览</a></li><li>我想确认边界：见 <a href="#限制与说明">限制与说明</a></li></ul><h2 id="入口与按钮" tabindex="-1">入口与按钮 <a class="header-anchor" href="#入口与按钮" aria-label="Permalink to &quot;入口与按钮&quot;">​</a></h2><p>入口在计划表顶栏，和 <a href="./ledger.html">收支账本</a> 的钱包按钮同一排。</p><table tabindex="0"><thead><tr><th style="text-align:center;">按钮图标</th><th style="text-align:left;">功能说明</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+r+'" width="20" style="display:inline-block;vertical-align:middle;margin:0;background:rgb(255, 255, 255);border-radius:6px;"></td><td style="text-align:left;"><strong>周 / 月 / 年</strong>：打开生活可视化图层；<strong>日视图</strong>：打开当天四类录入面板（当天还没有记录时，图标会带加号）</td></tr><tr><td style="text-align:center;"><img src="'+l+'" width="20" style="display:inline-block;vertical-align:middle;margin:0;background:rgb(193, 226, 255);border-radius:6px;"></td><td style="text-align:left;"><strong>周 / 月 / 年</strong>：图层已开，再点一次关闭</td></tr><tr><td style="text-align:center;"><img src="'+a+'" width="20" style="display:inline-block;vertical-align:middle;margin:0;background:rgb(193, 226, 255);border-radius:6px;"></td><td style="text-align:left;">表视图表头：给当前类加一行</td></tr><tr><td style="text-align:center;"><img src="'+e+'" width="20" style="display:inline-block;vertical-align:middle;margin:0;background:rgb(224, 224, 224);border-radius:6px;"></td><td style="text-align:left;">表视图行内：删除这一条</td></tr><tr><td style="text-align:center;"><img src="'+i+'" width="20" style="display:inline-block;vertical-align:middle;margin:0;background:rgb(224, 224, 224);border-radius:6px;"></td><td style="text-align:left;">活动 / 睡觉图视图：把未结束的一段标成当前时间结束</td></tr></tbody></table><ul><li><strong>日视图</strong>：点顶栏生活按钮，任务追踪区域换成四宫格录入面板。再点一次关闭，回到普通任务追踪。</li><li><strong>周 / 月 / 年</strong>：点顶栏宫格开关图层。开着时，计划表里的普通时间块会让位给生活图层。</li><li>从周 / 月 / 年点某天的 <strong>日期数字</strong>：打开该日的表视图预览（只看 / 改这一天）。电脑上 <strong>双击</strong> 日期、手机上 <strong>连点两下</strong> 日期，会进入该日的日视图。</li></ul><h2 id="四类记录" tabindex="-1">四类记录 <a class="header-anchor" href="#四类记录" aria-label="Permalink to &quot;四类记录&quot;">​</a></h2><p>界面上的「活动」是出门办事、如厕一类的时间段，图标是门，不是活动清单里的 Activity。</p><table tabindex="0"><thead><tr><th>类</th><th>图标</th><th>记什么</th></tr></thead><tbody><tr><td>喝水</td><td>💧</td><td>每一口的时间和毫升。点水滴图标按当前杯量加一口；当日目标可在图上改。</td></tr><tr><td>吃饭</td><td>🍚</td><td>时间、类型（正餐 / 甜点 / 水果）、吃了什么。点苹果图标加一条；点披萨 / 蛋糕 / 苹果在三种类型间切换。</td></tr><tr><td>活动</td><td>🚪</td><td>开始、结束、去干嘛。点门开始一段；未结束时点停止按钮记下结束时间。</td></tr><tr><td>睡觉</td><td>😴</td><td>入睡、醒来、梦什么。点月亮开始一段；未醒时点停止记下醒来时间。点云朵写梦。</td></tr></tbody></table><p>喝水默认杯量 <strong>250 ml</strong>（可改 50–1000），默认日目标 <strong>2000 ml</strong>。改杯量只影响之后新加的一口，已经记下的量不会跟着变。</p><h2 id="日视图录入" tabindex="-1">日视图录入 <a class="header-anchor" href="#日视图录入" aria-label="Permalink to &quot;日视图录入&quot;">​</a></h2><p>打开后是 <strong>2×2</strong>：喝水、吃饭、活动、睡觉。每一格都有 <strong>图</strong> 和 <strong>表</strong> 两种看法，点格内切换。</p><h3 id="图" tabindex="-1">图 <a class="header-anchor" href="#图" aria-label="Permalink to &quot;图&quot;">​</a></h3><ul><li>点该类的大图标加一条（喝水 = 加一口；吃饭 = 加一餐；活动 / 睡觉 = 开一段）。</li><li>只编辑 <strong>最后一条</strong>：时间、类型、备注、结束。更早的条目请切到表。</li><li>没有记录时，吃饭不会露出第二行编辑区。</li><li>活动 / 睡觉若上一段还没结束，再点大图标会问「上次结束了吗？」</li><li>睡觉可以跨午夜：昨晚没醒的一段，会继续出现在今天。</li></ul><h3 id="表" tabindex="-1">表 <a class="header-anchor" href="#表" aria-label="Permalink to &quot;表&quot;">​</a></h3><ul><li>列出当天该类全部记录，可改时间、量、类型、备注。</li><li>表头加号增行，行内删除。</li><li>活动 / 睡觉表里可以点表头时钟，把开始或结束填成当前时间。</li></ul><h2 id="周月年可视化" tabindex="-1">周月年可视化 <a class="header-anchor" href="#周月年可视化" aria-label="Permalink to &quot;周月年可视化&quot;">​</a></h2><p>打开图层后：</p><ul><li><strong>周</strong>：每天一列。喝水是水位波浪；吃饭、活动是散落的标记；睡觉是夜间色带和月亮。电脑上悬停看备注，手机上点标记看。</li><li><strong>月</strong>：每天四根竖条，从左到右是喝水、吃饭、活动、睡觉。喝水按 <strong>2 L</strong> 一杯的高度画（超过就加杯）；活动条默认按 <strong>2 小时</strong> 满格，当天更长时按向下取整的小时数放大。睡觉条下的时刻是<strong>当天最长那一觉的入睡点</strong>（跨夜只写入睡那天；夜班白天睡也写在入睡那天）。没有记录的格子不画条。</li><li><strong>年</strong>：当天有任一类生活记录，日期会着色。</li></ul><p>图层开着时，时间表上的普通块会隐藏，改显示这些生活标记。关掉图层即恢复。</p><h2 id="手机预览" tabindex="-1">手机预览 <a class="header-anchor" href="#手机预览" aria-label="Permalink to &quot;手机预览&quot;">​</a></h2><p>在周 / 月 / 年打开生活图层时：</p><ul><li>时间表和任务追踪区域会先藏起来，方便看计划表；<strong>不会改你平时的显示设置</strong>，关掉图层后还原。</li><li>顶栏里用来显示 / 隐藏这两块的按钮会跟着变成「当前看不见」的样子。再点它们：先退出预览，再打开对应区域。</li><li>打开生活录入面板或可视化时，右下角 FAB 会隐藏，避免挡住输入。</li><li>弹出键盘编辑时，页面会把当前输入滚到中上段，并尽量让该类的大图标仍在屏幕里。</li></ul><h2 id="限制与说明" tabindex="-1">限制与说明 <a class="header-anchor" href="#限制与说明" aria-label="Permalink to &quot;限制与说明&quot;">​</a></h2><ul><li>生活记录 <strong>不是</strong> 活动清单里的待办 / 预约，也不会出现在标签管理器里。系统会为每天四类各准备一条任务行，记录写在这些行上。</li><li>系统标签（喝水 / 吃饭 / 活动 / 睡觉）不参与年视图事项圆点取色，也不进 <a href="./tag.html">标签系统</a> 的管理面板。</li><li>云同步走任务字段，登录后与其它任务一起上传下载。本地备份 JSON 里同样在对应 <code>task</code> 上。</li><li>本软件不是医疗或营养日记：没有配餐库、没有睡眠分期，目标是在计划表旁边留下身体节律的痕迹。</li></ul>',27)]))}const P=o(g,[["render",h]]);export{q as __pageData,P as default};
